const products=[{id:'mug',name:'晨间陶瓷杯',category:'居家',price:69,detail:'把温暖，握在手心里',icon:'☕'},{id:'notebook',name:'留白手帐本',category:'文具',price:39,detail:'写下每一个灵光一现',icon:'📔'},{id:'bag',name:'日常帆布袋',category:'出行',price:59,detail:'轻装出发，装下喜欢',icon:'👜'},{id:'lamp',name:'暖光桌面灯',category:'居家',price:129,detail:'为晚上的自己留一盏灯',icon:'💡'}];
const $=s=>document.querySelector(s);const money=n=>'¥'+n.toFixed(2);let cart={};try{const saved=JSON.parse(localStorage.getItem('codx1-cart')||'{}');if(saved&&typeof saved==='object')for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0)cart[p.id]=Math.min(saved[p.id],99)}catch{}let category='全部';let timer;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2200)}
function renderProducts(){const q=$('#search').value.trim().toLowerCase();const found=products.filter(p=>(category==='全部'||p.category===category)&&(p.name+p.detail).toLowerCase().includes(q));$('#products').innerHTML=found.map(p=>`<article class="product"><div class="product-art"><small>EVERYDAY / ${p.category}</small><span class="object" aria-hidden="true">${p.icon}</span></div><h3>${p.name}</h3><p>${p.detail}</p><div class="product-bottom"><strong>${money(p.price)}</strong><button class="add" data-add="${p.id}" aria-label="添加${p.name}到购物袋">+</button></div></article>`).join('');$('#no-results').hidden=found.length!==0}
function renderCart(){let total=0,count=0;$('#cart-items').innerHTML=products.filter(p=>cart[p.id]).map(p=>{const qty=cart[p.id];total+=p.price*qty;count+=qty;return `<div class="cart-row"><span class="thumb" aria-hidden="true">${p.icon}</span><div class="cart-info"><p>${p.name}</p><p>${money(p.price)}</p><button class="remove" data-remove="${p.id}">移除</button></div><div class="cart-qty"><button data-change="${p.id}" data-delta="-1" aria-label="减少${p.name}数量">−</button><span>${qty}</span><button data-change="${p.id}" data-delta="1" aria-label="增加${p.name}数量">+</button></div></div>`}).join('')||'<p class="muted">购物袋还是空的，去挑一件喜欢的好物吧。</p>';$('#total').textContent=money(total);$('#count').textContent=count;$('#clear-cart').disabled=count===0;try{localStorage.setItem('codx1-cart',JSON.stringify(cart))}catch{}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const id=add.dataset.add;if((cart[id]||0)>=99){notify('单件商品最多添加 99 件');return}cart[id]=(cart[id]||0)+1;renderCart();notify('已加入购物袋')}const change=e.target.closest('[data-change]');if(change){const id=change.dataset.change;cart[id]=Math.max(0,Math.min(99,(cart[id]||0)+Number(change.dataset.delta)));if(!cart[id])delete cart[id];renderCart()}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];renderCart()}const filter=e.target.closest('[data-category]');if(filter){category=filter.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{const selected=b===filter;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});renderProducts()}});
$('#search').addEventListener('input',renderProducts);$('#cart-open').addEventListener('click',()=>$('#cart').showModal());$('#cart-close').addEventListener('click',()=>$('#cart').close());$('#cart').addEventListener('click',e=>{if(e.target===$('#cart')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#clear-cart').addEventListener('click',()=>{cart={};renderCart();notify('购物袋已清空')});
function calculateProfit(price,cost,shipping,fee,quantity){const revenue=price*quantity;const expense=(cost+shipping+price*fee/100)*quantity;return {revenue,expense,profit:revenue-expense,margin:revenue?(revenue-expense)/revenue*100:null}}
function updateProfit(){const inputs=['price','cost','shipping','fee','quantity'].map(id=>$('#'+id));if(!inputs.every(el=>el.validity.valid&&el.value!=='')){$('#profit').textContent='—';$('#margin').textContent='—';$('#calc-detail').textContent='请填写有效数字：金额不小于 0，费率为 0–100%，数量为正整数。';return}const result=calculateProfit(...inputs.map(el=>Number(el.value)));if(![result.revenue,result.expense,result.profit].every(Number.isFinite)){$('#profit').textContent='—';$('#margin').textContent='—';$('#calc-detail').textContent='数值过大，请减小输入。';return}$('#profit').textContent=money(result.profit);$('#profit').style.color=result.profit<0?'#b85b39':'';$('#margin').textContent=result.margin===null?'—':result.margin.toFixed(2)+'%';$('#calc-detail').textContent=`总收入 ${money(result.revenue)} · 总支出 ${money(result.expense)}${result.profit<0?' · 当前为亏损':''}`}
$('#profit-form').addEventListener('input',updateProfit);$('#profit-form').addEventListener('submit',e=>e.preventDefault());$('#profit-form').addEventListener('reset',()=>setTimeout(updateProfit,0));$('#year').textContent=new Date().getFullYear();document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('selected'))));renderProducts();renderCart();updateProfit();
